target.css:
:root {
  --ink: #202536;
  --paper: #fffdf7;
  --line: #ddd8ca;
  --plum: #6d4b72;
  --lavender: #eee6f2;
}

.screening-card {
  box-sizing: border-box;
  width: 480px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--paper);
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 16px 18px 14px;
  border-bottom: 1px solid var(--line);
}

.eyebrow {
  margin: 0 0 6px;
  color: var(--plum);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.1px;
}

.title-row {
  display: flex;
  align-items: center;
  gap: 10px;
}

h1 {
  margin: 0;
  font-size: 22px;
  line-height: 1;
  letter-spacing: -0.5px;
}

.status {
  padding: 4px 7px;
  border-radius: 999px;
  background: var(--lavender);
  color: var(--plum);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.showtime {
  padding-left: 16px;
  border-left: 1px solid var(--line);
  color: var(--plum);
  font-size: 11px;
  font-style: normal;
  font-weight: 700;
  line-height: 1.35;
  letter-spacing: 0.8px;
  text-align: right;
}

.showtime strong {
  color: var(--ink);
  font-size: 16px;
  letter-spacing: 0;
}

.details {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  padding: 14px 18px;
}

.detail {
  margin: 0;
}

.detail span,
.seat span {
  display: block;
  margin-bottom: 4px;
  color: var(--plum);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.8px;
}

.detail strong {
  font-size: 13px;
  line-height: 1.2;
}

.ticket-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 11px 18px;
  border-top: 1px solid var(--line);
  background: var(--lavender);
}

.seat {
  margin: 0;
}

.seat span {
  margin-bottom: 2px;
}

.seat strong {
  font-size: 14px;
}

.action {
  border: 0;
  border-radius: 7px;
  padding: 8px 12px;
  background: var(--plum);
  color: var(--paper);
  font-size: 12px;
  font-weight: 700;
}

